const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const http = this.helpers.httpRequest;
if (!SB_URL || !SB_KEY) return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({ url: SB_URL + '/rest/v1/' + path, json: true, timeout: 20000 }, opts, {
    headers: Object.assign({ apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' }, opts.headers || {}),
  }));
}

const PLATFORMS = [
  { platform: 'google', keyEnv: 'SERPAPI_KEY', via: 'serpapi' },
  { platform: 'google_ai_overview', keyEnv: 'SERPAPI_KEY', via: 'serpapi' },
  { platform: 'perplexity', keyEnv: 'PERPLEXITY_API_KEY', via: 'perplexity' },
  { platform: 'chatgpt', keyEnv: 'OPENAI_API_KEY', via: 'openai' },
  { platform: 'gemini', keyEnv: 'GEMINI_API_KEY', via: 'gemini' },
  { platform: 'claude', keyEnv: 'ANTHROPIC_API_KEY', via: 'anthropic' },
];

function normDomain(d) { if (!d) return ''; return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim(); }
function hostOf(u) { try { return normDomain(new URL(u).host); } catch (e) { return normDomain(u); } }
// EXACT host match (www-stripped). A product subdomain is NOT the company.
function urlMatchesDomain(u, dom) { if (!u || !dom) return false; return hostOf(u) === dom; }
function textIncludes(t, n) { if (!t || !n) return false; return String(t).toLowerCase().includes(String(n).toLowerCase()); }
// Strict brand match: the FULL entity name must appear (no first-two-words leniency).
function nameMatches(t, name) { return textIncludes(t, name); }
function collectUrls(obj, acc, depth) { acc = acc || []; depth = depth || 0; if (!obj || depth > 6) return acc; if (typeof obj === 'string') { const m = obj.match(/https?:\/\/[^\s\"'<>)\]]+/g); if (m) for (const u of m) acc.push(u); return acc; } if (Array.isArray(obj)) { for (const v of obj) collectUrls(v, acc, depth + 1); return acc; } if (typeof obj === 'object') { for (const k of Object.keys(obj)) collectUrls(obj[k], acc, depth + 1); } return acc; }
function baseRow(queryId, platform, extra) { return Object.assign({ query_id: queryId, platform: platform, ok: true, mentioned: false, cited: false, rank: null, snippet: null, source_urls: [], raw_response: null }, extra || {}); }
function collectText(output) { if (!output) return ''; try { const m = JSON.stringify(output).match(/\"text\":\"((?:[^\"\\]|\\.)*)\"/g); return m ? m.join(' ') : ''; } catch (e) { return ''; } }
function parseAnswer(entity, answerText, urls, rawMeta) {
  const domain = normDomain(entity.domain); const name = entity.name || '';
  const uniqueUrls = Array.from(new Set((urls || []).filter(Boolean)));
  const citedUrls = uniqueUrls.filter(function (u) { return urlMatchesDomain(u, domain); });
  const mentioned = (domain && (textIncludes(answerText, domain) || citedUrls.length > 0)) || (name && nameMatches(answerText, name));
  const snippet = answerText ? String(answerText).slice(0, 500) : null;
  return { ok: true, mentioned: Boolean(mentioned), cited: citedUrls.length > 0, source_urls: citedUrls.length ? citedUrls : uniqueUrls.slice(0, 10), snippet: snippet, raw_response: Object.assign({}, rawMeta, { answer_chars: answerText ? answerText.length : 0, citation_count: uniqueUrls.length }) };
}
async function probeSerpApi(apiKey, entity, q) {
  const data = await http({ method: 'GET', url: 'https://serpapi.com/search.json', qs: { engine: 'google', q: q, api_key: apiKey, hl: 'en', gl: 'in', num: 20 }, json: true, timeout: 20000 });
  const domain = normDomain(entity.domain); const name = entity.name || '';
  const organic = Array.isArray(data.organic_results) ? data.organic_results : [];
  let hit = null;
  for (const r of organic) { const link = r.link || r.displayed_link || ''; if ((domain && urlMatchesDomain(link, domain)) || (name && nameMatches(r.title || '', name))) { hit = r; break; } }
  const google = { ok: true, mentioned: Boolean(hit), cited: Boolean(hit), rank: hit ? (hit.position != null ? hit.position : null) : null, snippet: hit ? (hit.snippet || hit.title || null) : null, source_urls: hit && hit.link ? [hit.link] : [], raw_response: { engine: 'google', organic_count: organic.length, hit: hit || null } };
  // Only a real AI Overview block counts — NOT an ordinary answer_box.
  const ai = data.ai_overview || null;
  let aiMentioned = false, aiCited = false, aiUrls = [], aiSnippet = null;
  if (ai) { const aiText = JSON.stringify(ai); aiMentioned = (domain && textIncludes(aiText, domain)) || (name && nameMatches(aiText, name)); const refs = collectUrls(ai); aiUrls = refs.filter(function (u) { return urlMatchesDomain(u, domain); }); aiCited = aiUrls.length > 0; if (Array.isArray(ai.text_blocks) && ai.text_blocks[0]) aiSnippet = ai.text_blocks[0].snippet || ai.text_blocks[0].text || null; }
  const aiOverview = { ok: true, mentioned: Boolean(aiMentioned), cited: Boolean(aiCited), snippet: aiSnippet, source_urls: aiUrls, raw_response: ai ? { engine: 'google_ai_overview', present: true } : { engine: 'google_ai_overview', present: false } };
  return { google: google, google_ai_overview: aiOverview };
}
async function probePerplexity(apiKey, entity, q) { const data = await http({ method: 'POST', url: 'https://api.perplexity.ai/chat/completions', headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' }, body: { model: 'sonar', messages: [{ role: 'user', content: q }] }, json: true, timeout: 20000 }); const content = (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || ''; const citations = data.citations || data.search_results || []; const urls = (Array.isArray(citations) ? citations : []).map(function (c) { return typeof c === 'string' ? c : (c.url || c.link || ''); }).filter(Boolean); return parseAnswer(entity, content, urls, { engine: 'perplexity' }); }
async function probeOpenAI(apiKey, entity, q) { const data = await http({ method: 'POST', url: 'https://api.openai.com/v1/responses', headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' }, body: { model: 'gpt-4o-mini', tools: [{ type: 'web_search_preview' }], input: q }, json: true, timeout: 20000 }); const text = data.output_text || collectText(data.output); const urls = collectUrls(data.output || data); return parseAnswer(entity, text, urls, { engine: 'chatgpt' }); }
async function probeGemini(apiKey, entity, q) { const data = await http({ method: 'POST', url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent', qs: { key: apiKey }, headers: { 'Content-Type': 'application/json' }, body: { contents: [{ role: 'user', parts: [{ text: q }] }], tools: [{ google_search: {} }] }, json: true, timeout: 20000 }); const cand = data && data.candidates && data.candidates[0]; const parts = (cand && cand.content && cand.content.parts) || []; const text = parts.map(function (p) { return p.text || ''; }).join(' '); const chunks = (cand && cand.groundingMetadata && cand.groundingMetadata.groundingChunks) || []; const urls = chunks.map(function (c) { return c && c.web && c.web.uri; }).filter(Boolean); return parseAnswer(entity, text, urls.length ? urls : collectUrls(data), { engine: 'gemini' }); }
async function probeAnthropic(apiKey, entity, q) { const data = await http({ method: 'POST', url: 'https://api.anthropic.com/v1/messages', headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' }, body: { model: 'claude-3-5-haiku-latest', max_tokens: 1024, messages: [{ role: 'user', content: q }], tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 5 }] }, json: true, timeout: 20000 }); const blocks = Array.isArray(data.content) ? data.content : []; const text = blocks.filter(function (b) { return b.type === 'text'; }).map(function (b) { return b.text || ''; }).join(' '); const urls = collectUrls(data.content || data); return parseAnswer(entity, text, urls, { engine: 'claude' }); }

const entityItems = await rest('tracked_entities?select=id,name,domain');
const entityById = {}; for (const e of entityItems) if (e.id) entityById[e.id] = e;
const queries = await rest('target_queries?select=id,query_text,entity_id&active=eq.true');

const out = [];
for (const q of queries) {
  const entity = entityById[q.entity_id] || { name: null, domain: null };
  let serp = null;
  for (const cfg of PLATFORMS) {
    const apiKey = $env[cfg.keyEnv];
    if (!apiKey) { console.log('[visibility-probe] skip ' + cfg.platform + ' (no ' + cfg.keyEnv + ')'); continue; }
    try {
      if (cfg.via === 'serpapi') {
        if (cfg.platform === 'google') { serp = await probeSerpApi(apiKey, entity, q.query_text); out.push(baseRow(q.id, 'google', serp.google)); }
        else { const r = serp || (await probeSerpApi(apiKey, entity, q.query_text)); out.push(baseRow(q.id, 'google_ai_overview', r.google_ai_overview)); }
      } else {
        let partial;
        if (cfg.via === 'perplexity') partial = await probePerplexity(apiKey, entity, q.query_text);
        else if (cfg.via === 'openai') partial = await probeOpenAI(apiKey, entity, q.query_text);
        else if (cfg.via === 'gemini') partial = await probeGemini(apiKey, entity, q.query_text);
        else if (cfg.via === 'anthropic') partial = await probeAnthropic(apiKey, entity, q.query_text);
        out.push(baseRow(q.id, cfg.platform, partial));
      }
    } catch (err) {
      // Failed probe: ok=false so scores EXCLUDE it (not counted as real invisibility).
      console.log('[visibility-probe] ' + cfg.platform + ' failed for ' + q.id + ': ' + (err && err.message));
      out.push(baseRow(q.id, cfg.platform, { ok: false, mentioned: false, cited: false, raw_response: { error: String((err && err.message) || err), platform: cfg.platform } }));
    }
  }
}

if (out.length) {
  for (let i = 0; i < out.length; i += 100) {
    const chunk = out.slice(i, i + 100);
    await rest('visibility_checks', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: chunk });
  }
}
return [{ json: { inserted: out.length, queries: queries.length } }];
